input.content:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses and buys books online"
        bookshop = softwareSystem "Bookshop" "An online bookshop for buying books" {
            webStore = container "Web Store" "A web application that lets customers browse the catalogue and place orders" "Web Application"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Service"
        }

        customer -> webStore "Browses the catalogue and places orders using" "HTTPS"
        webStore -> orderProcessor "Sends order details to" "gRPC"
    }

    views {
        systemContext bookshop "SystemContext" "Shows the Customer interacting with the Bookshop" {
            include *
            autoLayout
        }
        workspaceView "SystemContext"
    }
}

